dule -->\n\nEditionRowTablesComponent->EditionRowTablesModule\n\n\n\n\n\nEditionRowTablesRoutingModule\n\nEditionRowTablesRoutingModule\n\nEditionRowTablesModule -->\n\nEditionRowTablesRoutingModule->EditionRowTablesModule\n\n\n\n\n\nSharedModule\n\nSharedModule\n\nEditionRowTablesModule -->\n\nSharedModule->EditionRowTablesModule\n\n\n\n\n\n\n    \n    \n    \n        Zoom in\n        Reset\n        Zoom out\n    \n\n\n\n\n\n    \n        Info\n    \n    \n        Source\n    \n\n\n\n    \n\n        \n            File\n        \n        \n            src/app/views/edition-view/edition-outlets/edition-row-tables/edition-row-tables.module.ts\n        \n\n\n\n        \n            Description\n        \n        \n            The EditionRowTables module.\nIt embeds the EditionRowTablesComponent and its\nrouting definition\nas well as the SharedModule.\n\n        \n\n\n        \n            \n                \n                    Declarations\n                    \n                        \n                            EditionRowTablesComponent\n                        \n                    \n                \n                \n                    Imports\n                    \n                        \n                            EditionRowTablesRoutingModule\n                        \n                        \n                            SharedModule\n                        \n                    \n                \n            \n        \n\n\n    \n\n\n    \n        import { NgModule } from '@angular/core';\n\nimport { SharedModule } from '@awg-shared/shared.module';\n\nimport { EditionRowTablesRoutingModule, routedEditionRowTablesComponents } from './edition-row-tables-routing.module';\n\n/**\n * The EditionRowTables module.\n *\n * It embeds the {@link EditionRowTablesComponent} and its\n * [routing definition]{@link EditionRowTablesRoutingModule}\n * as well as the {@link SharedModule}.\n */\n@NgModule({\n    imports: [SharedModule, EditionRowTablesRoutingModule],\